def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    refs = [{'url': u, 'title': t + '；僅研究題型與能力方向，未複製原題。', 'year': '113-114', 'subject': 'social', 'locator': loc, 'observedPattern': '公開社會科現代經濟資料題研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'} for u, t, loc in SOURCES]
    steps = [f'讀題定位：圈出「{tag}」與題目給的群體、地區、成本、服務或成效指標。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合現代經濟挑戰的多因素判讀。', '排除誘答：檢查是否只看平均值、申請量、總量或單一群體，忽略分配與長期結果。', '結論回查：確認分母、期間、空間與群體都清楚，避免把局部改善說成全面解決。']
